CREATE TABLE IF NOT EXISTS "Artikel" (
	"ArtikelID" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"Bezeichnung" TEXT NOT NULL UNIQUE,
	PRIMARY KEY("ArtikelID")
);

CREATE TABLE IF NOT EXISTS "Mitarbeiter" (
	"MitarbeiterID" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	PRIMARY KEY("MitarbeiterID")
);

CREATE TABLE IF NOT EXISTS "Lagerbewegung" (
	"AktionsID" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"ArtikelID" INTEGER NOT NULL,
	"Bewegungsvolumen" INTEGER NOT NULL,
	"MitarbeiterID" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"Bewegungsart" VARCHAR(255) NOT NULL CHECK(Bewegungsart IN ('Eingang', 'Ausgang')),
	PRIMARY KEY("AktionsID")
) INHERITS ("Artikel");

ALTER TABLE "Artikel"
ADD FOREIGN KEY("ArtikelID") REFERENCES "Lagerbewegung"("ArtikelID")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "Lagerbewegung"
ADD FOREIGN KEY("MitarbeiterID") REFERENCES "Mitarbeiter"("MitarbeiterID")
ON UPDATE NO ACTION ON DELETE NO ACTION;